def __init__(self) -> None:
        # (blocks held per group, num_computed_tokens, num_scheduled_tokens)
        self.steps: list[tuple[list[int], int, int]] = []
        self.num_spec_tokens_to_schedule: list[int] = []
        self._held: dict[str, list[int]] = {}

def execute_model(self, scheduler_output) -> None:
        if scheduler_output.total_num_scheduled_tokens:
            self.num_spec_tokens_to_schedule.append(
                scheduler_output.num_spec_tokens_to_schedule
            )
        for new_req in scheduler_output.scheduled_new_reqs:
            self._held[new_req.req_id] = [len(ids) for ids in new_req.block_ids]
            self._record(new_req.req_id, new_req.num_computed_tokens, scheduler_output)
        cached = scheduler_output.scheduled_cached_reqs
        for i, req_id in enumerate(cached.req_ids):
            new_block_ids = cached.new_block_ids[i]
            if new_block_ids is not None:
                self._held[req_id] = [
                    held + len(ids)
                    for held, ids in zip(self._held[req_id], new_block_ids)
                ]
            self._record(req_id, cached.num_computed_tokens[i], scheduler_output)

def _record(self, req_id: str, num_computed: int, scheduler_output) -> None:
        self.steps.append(
            (
                list(self._held[req_id]),
                num_computed,
                scheduler_output.num_scheduled_tokens[req_id],
            )
        )

def __init__(self, warmup_committable_blocks: int) -> None:
        self.warmup_committable_blocks = warmup_committable_blocks
        self.commits: list[int] = []

def execute_model(scheduler_output) -> None:
        for new_req in scheduler_output.scheduled_new_reqs:
            requested[new_req.req_id] = new_req.sampling_params.prompt_logprobs
        recorder.execute_model(scheduler_output)

def _init_ray_for_weight_transfer() -> None:
    if ray.is_initialized():
        return
    ray.init(
        ignore_reinit_error=True,
        runtime_env={
            "env_vars": {
                "RAY_EXPERIMENTAL_NOSET_CUDA_VISIBLE_DEVICES": "1",
                "RAY_EXPERIMENTAL_NOSET_HIP_VISIBLE_DEVICES": "1",
                "RAY_EXPERIMENTAL_NOSET_ROCR_VISIBLE_DEVICES": "1",
            }
        },
    )

def _get_ray_assigned_device() -> torch.device:
    gpu_ids = ray.get_gpu_ids()
    if not gpu_ids:
        return torch.device("cuda:0")
    return torch.device(f"cuda:{int(gpu_ids[0])}")

class MultiSourceInferenceWorker:
    def __init__(self, worker_rank: int, num_workers: int):
        import contextlib

        device = _set_ray_assigned_device()

        from vllm.config.weight_transfer import WeightTransferConfig
        from vllm.distributed.weight_transfer.nccl_engine import (
            NCCLWeightTransferEngine,
        )

        class Recorder(torch.nn.Module):
            def __init__(self):
                super().__init__()
                self.received: dict[str, float] = {}
                self.load_counts: dict[str, int] = {}

            def load_weights(self, weights):
                for name, tensor in weights:
                    self.received[name] = tensor.sum().item()
                    self.load_counts[name] = self.load_counts.get(name, 0) + 1

        self.recorder = Recorder()
        self.engine = NCCLWeightTransferEngine(
            WeightTransferConfig(backend="nccl"),
            create_mock_vllm_config(rank=worker_rank, world_size=num_workers),
            device,
            self.recorder,
        )
        import vllm.config as vllm_config_mod

        vllm_config_mod.set_current_vllm_config = lambda cfg: contextlib.nullcontext()

    def ready(self):
        return True

    def initialize(self, init_info):
        self.engine.init_transfer_engine(self.engine.parse_init_info(init_info))

    def update(self, update_info):
        self.engine.receive_weights(self.engine.parse_update_info(update_info))

    def results(self):
        torch.accelerator.synchronize()
        results = {
            "received": self.recorder.received,
            "load_counts": self.recorder.load_counts,
        }
        self.engine.shutdown()
        return results

def trainer_send_from_source(
    receivers,
    master_address: str,
    master_port: int,
    world_size: int,
    num_sources: int,
    rank: int,
    tensor_shape: list[int],
    num_tensors_per_source: int,
    packed: bool,
) -> bool:
    from functools import cached_property

    device = _set_ray_assigned_device()

    from vllm.distributed.weight_transfer import (
        ParamMeta,
        WeightSource,
        WeightTransferTrainerFactory,
    )
    from vllm.distributed.weight_transfer.nccl_engine import NCCLTrainerInitInfo

    class Source(WeightSource):
        """Rank r owns (and broadcasts) `source_r.*`, like a pipeline stage."""

        @cached_property
        def metadata(self):
            return [
                ParamMeta(
                    f"source_{r}.weight_{i}",
                    torch.float32,
                    tuple(tensor_shape),
                    owners=(r,),
                )
                for r in range(num_sources)
                for i in range(num_tensors_per_source)
            ]

        def iter_full(self):
            for i in range(num_tensors_per_source):
                value = rank * num_tensors_per_source + i + 1
                yield (
                    f"source_{rank}.weight_{i}",
                    torch.full(tensor_shape, value, dtype=torch.float32, device=device),
                )

    class Client:
        def call(self, method, *args):
            return ray.get(
                [getattr(receiver, method).remote(*args) for receiver in receivers]
            )

        def init_weight_transfer_engine(self, init_info):
            self.call("initialize", init_info)

        def start_weight_update(self):
            pass

        def update_weights(self, update_info):
            self.call("update", update_info)

        def finish_weight_update(self, weight_version=None):
            pass

    engine = WeightTransferTrainerFactory.trainer_init(
        NCCLTrainerInitInfo(
            master_address=master_address,
            master_port=master_port,
            world_size=world_size,
            rank=rank,
            packed=packed,
            packed_buffer_size_bytes=1024,
        ),
        client=Client(),
        source=Source(),
    )
    for _ in range(2):
        engine.send_weights()
    engine.shutdown()
    return True

def get_physical_gpu_id(device_index: int = 0) -> str:
